def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 100:
        return 'D'

    rem = 99 - n
    my_last, opp_last = history[-1]

    opp_d = 0
    my_d = 0
    for m, o in history:
        if m == 'D':
            my_d += 1
        if o == 'D':
            opp_d += 1

    w = 12 if n >= 12 else n
    recent_d = 0
    for i in range(n - w, n):
        if history[i][1] == 'D':
            recent_d += 1

    punished = 0
    forgiven = 0
    for i in range(n - 1):
        if history[i][0] == 'D':
            if history[i + 1][1] == 'D':
                punished += 1
            else:
                forgiven += 1

    opp_d_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_d_streak += 1
        else:
            break

    opp_c_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'C':
            opp_c_streak += 1
        else:
            break

    mutual_d_run = 0
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'D' and history[i][1] == 'D':
            mutual_d_run += 1
        else:
            break

    total_rate = opp_d / n
    recent_rate = recent_d / w

    provoked = (opp_last == 'D' and n >= 2 and history[-2][0] == 'D')

    hostile = (total_rate >= 0.62) or (recent_rate >= 0.72 and opp_d > 4) or (opp_d_streak >= 7)
    friendly = (total_rate <= 0.30) and (recent_rate <= 0.40) and (opp_d_streak <= 4)

    exploitable = (
        punished == 0
        and my_d >= 1
        and forgiven >= 1
        and opp_last == 'C'
        and recent_d <= 2
        and friendly
    )

    retaliatory = punished > 0 and punished >= forgiven and total_rate <= 0.60

    if rem == 0:
        return 'D'

    if hostile:
        if mutual_d_run >= 4 and total_rate < 0.85 and rng.random() < 0.18:
            return 'C'
        return 'D'

    if opp_last == 'D':
        # Opponent appears to be retaliating to our recent defection.
        # Show contrition to avoid a permanent punishment loop unless the conflict is entrenched.
        if provoked:
            if mutual_d_run >= 3 and total_rate < 0.5 and rng.random() < 0.20:
                return 'D'
            return 'C'

        # Mutual defection with no clear provocation: try to break a short death spiral.
        if my_last == 'D':
            if friendly and mutual_d_run >= 2:
                if rng.random() < 0.70:
                    return 'C'
            return 'D'

        # Unprovoked defection from a cooperative-looking partner: punish once.
        if friendly:
            return 'D'

        # Mixed opponent: sometimes forgive isolated/unclear punishment, otherwise retaliate.
        if total_rate <= 0.45 and recent_rate <= 0.50 and rng.random() < 0.25:
            return 'C'
        return 'D'

    # Opponent cooperated last round.
    if my_last == 'D':
        if exploitable:
            if rem <= 3:
                return 'D'
            if opp_c_streak >= 5 and rng.random() < 0.10:
                return 'D'
            return 'C'

        if retaliatory:
            return 'C'

        # We may have just defected after a cooperative run. Return to cooperation
        # to observe the opponent's response instead of escalating immediately.
        return 'C'

    # Both cooperated last round.
    if exploitable:
        if rem <= 3:
            return 'D'
        if rem <= 10 and opp_c_streak >= 10 and rng.random() < 0.06:
            return 'D'
        return 'C'

    # A controlled late probe: if a friendly opponent has maintained a long cooperative
    # streak, test whether it can tolerate one defection without starting permanent retaliation.
    if (
        friendly
        and opp_c_streak >= 15
        and my_d == 0
        and punished == 0
        and forgiven == 0
        and 6 < rem < 25
    ):
        return 'D'

    # Defectors with recent bad behavior should not be rewarded with cooperation.
    if recent_rate > 0.45 and rng.random() < 0.25:
        return 'D'

    return 'C'
